input.old_string:
case "$key" in
  r|R) break ;;
  f) FILTER="fail"; FILTER_LABEL="FAILS"; break ;;
  i) FILTER="inference"; FILTER_LABEL="INFERENCE"; break ;;
  v) FILTER="voice"; FILTER_LABEL="VOICE"; break ;;
  h) FILTER="hooks"; FILTER_LABEL="HOOKS"; break ;;
  a) FILTER="all"; FILTER_LABEL="ALL"; break ;;
  q|Q) exit 0 ;;
esac

input.new_string:
case "$key" in
  r|R) break ;;
  q|Q) exit 0 ;;
esac
